BEGIN;

-- Payment Attempt stores one canonical QR representation: the raw VietQR EMV
-- payload generated by Payment. Retire image/URL attempts created before this
-- invariant so clients never need a second rendering path.
UPDATE commerce_payment_attempts
SET status = 'expired',
    next_action_kind = 'none',
    qr_payload = '',
    action_expires_at = NULL,
    failure_code = 'legacy_qr_payload_retired',
    failure_detail = 'Create a new payment attempt using the canonical VietQR EMV payload.',
    updated_at = NOW()
WHERE next_action_kind = 'display_qr'
  AND qr_payload !~ '^000201';

ALTER TABLE commerce_payment_attempts
    ADD CONSTRAINT commerce_payment_attempts_canonical_qr_payload_ck
    CHECK (
        (next_action_kind = 'display_qr' AND qr_payload ~ '^000201' AND redirect_url = '')
        OR
        (next_action_kind <> 'display_qr' AND qr_payload = '')
    );

COMMIT;
